sql_query:
SELECT "Year"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Year", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Name of ICI", '')) = 'Ipilimumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Year" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Year", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Included in MA", '')) = 'No' AND TRIM(COALESCE("Name of ICI", '')) = 'Ipilimumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_era_bucket(source_value) AS "era"
FROM base;
